  "headline": "FDA's records show cisatracurium besylate is not on the shortage list as of 2026-10-21; Hospira, a Pfizer Company, posted a discontinuation on 2026-09-11 with supply expected to exhaust November 2026",
  "headline_cites": ["D4", "E5"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include cisatracurium besylate as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Hospira, Inc., a Pfizer Company, posted a discontinuation notice on 2026-09-11 stating supply is expected to exhaust November 2026.",
      "cites": ["E5"]
    },
    {
      "text": "No public FDA signal exists at the plants supplying our current inventory.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 39 vials at 3.5 per day for 11.2 days on hand; Corvale General holds 126 vials at 4.1 per day for 31 days on hand; Corvale Lakeside holds 23 vials at 0.8 per day for 29.6 days on hand.",
      "cites": ["D1", "D2", "D3"]
    },
    {
      "text": "The rule-based best option is to buy from Armas Pharmaceuticals, which is not on FDA's shortage list today.",
      "cites": ["D5"]
    },
    {
      "text": "Alternative manufacturers Avenacy, LLC and Camber Pharmaceuticals Inc. are also not on FDA's shortage list today.",
      "cites": ["D6", "D7"]
    }
  ]
}
